import type { MemoryCardSchedule, RecallGrade, VocabularyItemId } from "@verbysia/domain";

export interface MemoryCard extends MemoryCardSchedule {
  userId: string;
  vocabularyItemId: VocabularyItemId;
  version: number;
  lastReviewedAt: Date | null;
  createdAt: Date;
}

export interface MemoryReviewLog {
  vocabularyItemId: VocabularyItemId;
  grade: RecallGrade;
  usedHint: boolean;
  reviewedAt: Date;
}

export interface RecordReviewInput {
  userId: string;
  vocabularyItemId: VocabularyItemId;
  /** Generated by the client per answer: the same id twice is one review (safe retries). */
  clientReviewId: string;
  grade: RecallGrade;
  usedHint: boolean;
  now: Date;
}

export interface RecordReviewResult {
  card: MemoryCard;
  /** True when this `clientReviewId` had already been recorded — nothing changed this time. */
  duplicate: boolean;
}

export interface MemoryCardRepository {
  listByUser(userId: string): Promise<readonly MemoryCard[]>;
  /**
   * Applies one answer atomically: reads the card under a row lock, schedules it with SM-2,
   * writes it with `version + 1` and appends the review — or, if `clientReviewId` is already
   * recorded, returns the current card unchanged.
   */
  recordReview(input: RecordReviewInput): Promise<RecordReviewResult>;
  listReviewsSince(userId: string, since: Date): Promise<readonly MemoryReviewLog[]>;
}
